SC_MODULE(conv_bn_act_pool_2_X_slice2) {


static const unsigned DataWidth = 32;
static const unsigned AddressRange = 4800;
static const unsigned AddressWidth = 13;

sc_core::sc_in <sc_lv<AddressWidth> > address0;
sc_core::sc_in<sc_logic> ce0;
sc_core::sc_out <sc_lv<DataWidth> > q0;
sc_core::sc_in<sc_logic> reset;
sc_core::sc_in<bool> clk;


conv_bn_act_pool_2_X_slice2_ram* meminst;


SC_CTOR(conv_bn_act_pool_2_X_slice2) {
meminst = new conv_bn_act_pool_2_X_slice2_ram("conv_bn_act_pool_2_X_slice2_ram");
meminst->address0(address0);
meminst->ce0(ce0);
meminst->q0(q0);

meminst->reset(reset);
meminst->clk(clk);
}
~conv_bn_act_pool_2_X_slice2() {
    delete meminst;
}


};//endmodule
